//! Anti-aliased monospaced text from an `OSXF` coverage atlas
//! (generated by `scripts/gen-assets.py`).

use crate::{Color, Rect, Surface};

#[derive(Debug, PartialEq, Eq, Clone, Copy)]
pub enum AssetError {
    BadMagic,
    Truncated,
    BadDimensions,
}

#[derive(Clone, Copy)]
pub struct Font<'a> {
    first: u32,
    count: u32,
    cell_w: u32,
    cell_h: u32,
    baseline: u32,
    glyphs: &'a [u8],
}

pub(crate) fn read_u32(b: &[u8], off: usize) -> Result<u32, AssetError> {
    let s = b.get(off..off + 4).ok_or(AssetError::Truncated)?;
    Ok(u32::from_le_bytes([s[0], s[1], s[2], s[3]]))
}

impl<'a> Font<'a> {
    const HEADER: usize = 24;

    pub fn parse(bytes: &'a [u8]) -> Result<Self, AssetError> {
        if bytes.get(0..4) != Some(b"OSXF") {
            return Err(AssetError::BadMagic);
        }
        let first = read_u32(bytes, 4)?;
        let count = read_u32(bytes, 8)?;
        let cell_w = read_u32(bytes, 12)?;
        let cell_h = read_u32(bytes, 16)?;
        let baseline = read_u32(bytes, 20)?;
        if count == 0 || cell_w == 0 || cell_h == 0 || cell_w > 256 || cell_h > 256 {
            return Err(AssetError::BadDimensions);
        }
        let len = (count as usize).checked_mul(cell_w as usize * cell_h as usize).ok_or(AssetError::BadDimensions)?;
        let glyphs = bytes.get(Self::HEADER..Self::HEADER + len).ok_or(AssetError::Truncated)?;
        Ok(Font { first, count, cell_w, cell_h, baseline, glyphs })
    }

    pub fn cell_width(&self) -> u32 {
        self.cell_w
    }

    pub fn line_height(&self) -> u32 {
        self.cell_h
    }

    pub fn baseline(&self) -> u32 {
        self.baseline
    }

    /// Width in pixels of `text` (one cell per `char`).
    pub fn measure(&self, text: &str) -> u32 {
        text.chars().count() as u32 * self.cell_w
    }

    fn glyph(&self, ch: char) -> &'a [u8] {
        let code = ch as u32;
        let index = if code >= self.first && code < self.first + self.count {
            code - self.first
        } else {
            // Unsupported characters render as '?', which every atlas contains.
            ('?' as u32).saturating_sub(self.first).min(self.count - 1)
        };
        let size = (self.cell_w * self.cell_h) as usize;
        let start = index as usize * size;
        &self.glyphs[start..start + size]
    }

    /// Draws `text` with its top-left cell corner at (`x`, `y`). Returns the
    /// rectangle that was touched.
    pub fn draw(&self, s: &mut Surface, x: i32, y: i32, text: &str, c: Color, alpha: u32) -> Rect {
        let mut pen = x;
        for ch in text.chars() {
            if ch != ' ' {
                let g = self.glyph(ch);
                for gy in 0..self.cell_h {
                    let row = &g[(gy * self.cell_w) as usize..((gy + 1) * self.cell_w) as usize];
                    for (gx, &cov) in row.iter().enumerate() {
                        if cov != 0 {
                            let a = (cov as u32 * alpha + 127) / 255;
                            s.blend_px(pen + gx as i32, y + gy as i32, c, a);
                        }
                    }
                }
            }
            pen += self.cell_w as i32;
        }
        Rect::new(x, y, (pen - x) as u32, self.cell_h)
    }

    /// Draws `text` horizontally centred on `cx`.
    pub fn draw_centered(&self, s: &mut Surface, cx: i32, y: i32, text: &str, c: Color, alpha: u32) -> Rect {
        let w = self.measure(text) as i32;
        self.draw(s, cx - w / 2, y, text, c, alpha)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    static MONO16: &[u8] = include_bytes!("../../assets/mono16.osxf");

    #[test]
    fn parses_generated_atlas() {
        let f = Font::parse(MONO16).unwrap();
        assert_eq!(f.cell_width(), 10);
        assert_eq!(f.line_height(), 21);
        assert_eq!(f.measure("OSyx"), 40);
        assert_eq!(f.measure("zażółć"), 60, "measured per char, not per byte");
    }

    #[test]
    fn rejects_malformed_atlases() {
        assert_eq!(Font::parse(b"NOPE").err(), Some(AssetError::BadMagic));
        assert_eq!(Font::parse(&MONO16[..30]).err(), Some(AssetError::Truncated));
        let mut bad = MONO16[..24].to_vec();
        bad[12..16].copy_from_slice(&0u32.to_le_bytes());
        assert_eq!(Font::parse(&bad).err(), Some(AssetError::BadDimensions));
    }

    #[test]
    fn draws_ink_inside_reported_rect() {
        let f = Font::parse(MONO16).unwrap();
        let mut buf = vec_zeroed(64 * 32);
        let mut s = Surface::new(&mut buf, 64, 32, 64).unwrap();
        let r = f.draw(&mut s, 2, 3, "A?", 0xFFFFFF, 255);
        assert_eq!(r, Rect::new(2, 3, 20, 21));
        let mut ink = 0;
        for y in 0..32 {
            for x in 0..64 {
                if s.get(x, y).unwrap() != 0 {
                    ink += 1;
                    assert!(x >= r.x && (x as i64) < r.right() && y >= r.y && (y as i64) < r.bottom());
                }
            }
        }
        assert!(ink > 20, "glyphs must produce visible pixels");
    }

    fn vec_zeroed(n: usize) -> std::vec::Vec<u32> {
        std::vec![0; n]
    }

    extern crate std;
}
